import React from "react";
import {navigate} from 'gatsby';

const defaultIndex = () => {
  if (typeof window !== 'undefined') {
    const brandIntro = (value) => navigate(value);
    const path = "default";
    return (
      <div onLoad={brandIntro(`/${path}`)}></div>
    );
  }
  return null;
};

export default defaultIndex;
